standards_pin_error() {
  printf 'standards pin: %s\n' "$*" >&2
  return 1
}

standards_pin_valid() {
  [[ "$1" =~ ^[0-9a-f]{40}$ ]] || standards_pin_error "expected a non-empty 40-character lowercase SHA"
}

standards_pin_record() {
  local workspace_key root
  root="$(cd -- "$1" && pwd -P)" || return 1
  workspace_key="$(printf '%s' "$root" | git hash-object --stdin)" || return 1
  printf '%s/standards/cloud/%s.pin\n' "${XDG_STATE_HOME:-$HOME/.local/state}" "$workspace_key"
}

standards_verify_checkout() {
  local root="$1" pin="$2" checkout="$1/.standards-config"
  standards_pin_valid "$pin" || return 1
  if [ -L "$checkout" ] || [ ! -d "$checkout/.git" ]; then
    standards_pin_error "$root needs a real .standards-config Git clone"
    return 1
  fi
  local origin shallow head dirty
  origin="$(git -C "$checkout" config --get remote.origin.url)" || return 1
  shallow="$(git -C "$checkout" rev-parse --is-shallow-repository)" || return 1
  head="$(git -C "$checkout" rev-parse HEAD)" || return 1
  dirty="$(git -C "$checkout" status --porcelain --untracked-files=all)" || return 1
  if [ "$origin" != 'https://github.com/Rubio-Enterprises/standards.git' ] ||
    [ "$shallow" != false ] || [ "$head" != "$pin" ] || [ -n "$dirty" ]; then
    standards_pin_error "checkout must be clean, full-history, at the expected pin, with the credential-free origin"
    return 1
  fi
}

standards_require_ready() {
  local root pin="$2" mise_bin="${3:-mise}" status
  root="$(cd -- "$1" && pwd -P)" || return 1
  standards_verify_checkout "$root" "$pin" || return 1
  command -v jq >/dev/null 2>&1 || {
    standards_pin_error 'jq is required to validate the effective standards declaration'
    return 1
  }
  if ! status="$(STANDARDS_PIN="$pin" "$mise_bin" -C "$root" bootstrap repos status --missing --json 2>&1)"; then
    standards_pin_error 'mise repo status failed; check the standards declaration and checkout'
    return 1
  fi
  # Treat skipped-declaration warnings as invalid JSON, not a valid fallback
  if ! jq -e --arg pin "$pin" --arg path "$root/.standards-config" '
    .repos | any(.path_raw == ".standards-config" and .path == $path and
      .url == "https://github.com/Rubio-Enterprises/standards.git" and
      .ref == $pin and .current_sha == $pin and .state == "current")
  ' <<<"$status" >/dev/null 2>&1; then
    standards_pin_error 'mise must declare .standards-config at the independent STANDARDS_PIN with no depth'
    return 1
  fi
  "$mise_bin" -C "$root" tasks --json >/dev/null || return 1
}

standards_restore_pin() {
  local root="$1" record expected
  record="$(standards_pin_record "$root")" || return 1
  if [ "${STANDARDS_PIN+x}" != x ] && [ ! -e "$record" ]; then
    return 0
  fi
  if [ "${STANDARDS_PIN+x}" = x ]; then
    standards_pin_valid "$STANDARDS_PIN" || return 1
  fi
  if [ -e "$record" ]; then
    if [ ! -f "$record" ] || [ -L "$record" ]; then
      standards_pin_error "provisioner record must be a regular file"
      return 1
    fi
    expected="$(<"$record")"
    standards_pin_valid "$expected" || return 1
    if [ "${STANDARDS_PIN+x}" = x ] && [ "$STANDARDS_PIN" != "$expected" ]; then
      standards_pin_error "environment pin disagrees with the independent provisioner record"
      return 1
    fi
  else
    expected="$STANDARDS_PIN"
  fi
  standards_verify_checkout "$root" "$expected" || return 1
  export STANDARDS_PIN="$expected"
  if [ -n "${CLAUDE_ENV_FILE:-}" ]; then
    printf 'export STANDARDS_PIN=%s\n' "$STANDARDS_PIN" >>"$CLAUDE_ENV_FILE" || return 1
  fi
}

standards_devcontainer_setup() {
  local root="$1" mode="${2:-}" pin derived=false
  if [ "${STANDARDS_PIN+x}" != x ]; then
    if [ "${CI:-}" = true ] || [ "${CLAUDE_CODE_REMOTE:-}" = true ]; then
      standards_pin_error 'CI and cloud containers require an independently supplied STANDARDS_PIN'
      return 1
    fi
    pin="$(git -C "$root/.standards-config" rev-parse HEAD 2>/dev/null)" || {
      standards_pin_error 'run mise bootstrap --only repos,tools --yes on the laptop HOST before opening the Dev Container'
      return 1
    }
    export STANDARDS_PIN="$pin"
    derived=true
  fi
  standards_verify_checkout "$root" "$STANDARDS_PIN" || return 1
  if [ "$derived" = true ] && [ "${STANDARDS_DEVCONTAINER:-}" = 1 ] &&
    ! bash -c 'unset -f standards_devcontainer_setup; source "$1"; declare -F standards_devcontainer_setup >/dev/null' _ \
      "$root/.standards-config/template/scripts/common/standards-pin.sh" >/dev/null 2>&1; then
    standards_pin_error 'prepared standards predate container setup; run mise bootstrap --only repos,tools --yes on the laptop HOST'
    return 1
  fi
  mise trust "$root/.mise.toml" >/dev/null || return 1
  standards_require_ready "$root" "$STANDARDS_PIN" || return 1
  if [ "$mode" != --check-only ]; then
    mise -C "$root" run setup
  fi
}

standards_require_cloud_ready() {
  local root="$1"
  standards_restore_pin "$root" || return 1
  if [ "${STANDARDS_PIN+x}" != x ]; then
    standards_pin_error 'cloud SessionStart has no provisioned pin; re-paste the current web Setup wrapper, bump CACHE_EPOCH and rebuild the environment cache before retrying'
    return 1
  fi
  standards_pin_valid "$STANDARDS_PIN" || return 1
  standards_require_ready "$root" "$STANDARDS_PIN"
}

standards_cloud_container() (
  set -euo pipefail
  local root="$1" auth state image
  local cli=(devcontainer)
  [ "${CLAUDE_CODE_REMOTE:-}" = true ] || exit 0
  standards_require_cloud_ready "$root"
  if ! command -v devcontainer >/dev/null || [ "$(devcontainer --version)" != 0.89.0 ]; then
    cli=(mise exec npm:@devcontainers/cli@0.89.0 -- devcontainer)
  fi
  [[ "$("${cli[@]}" --version)" = 0.89.0 ]] || {
    standards_pin_error 'cloud image execution requires Dev Container CLI 0.89.0'
    exit 1
  }
  state="${XDG_STATE_HOME:-$HOME/.local/state}/standards/cloud"
  mkdir -p "$state"
  if ! docker info >/dev/null 2>&1; then
    command -v dockerd >/dev/null || {
      standards_pin_error 'dockerd is required in the cloud environment'
      exit 1
    }
    dockerd >"$state/dockerd.log" 2>&1 &
    for ((attempt = 0; attempt < 30; attempt++)); do
      if docker info >/dev/null 2>&1; then break; fi
      sleep 1
    done
    docker info >/dev/null 2>&1 || {
      standards_pin_error "dockerd did not become ready; inspect $state/dockerd.log"
      exit 1
    }
  fi
  image="$(jq -er '.image | strings' "$root/.devcontainer/devcontainer.json")"
  [[ "$image" =~ ^ghcr\.io/rubio-enterprises/[a-z0-9_.-]+/devcontainer:main$ ]] || {
    standards_pin_error 'cloud requires the repository image runtime definition'
    exit 1
  }
  : "${GHCR_USERNAME:?cloud requires the existing GHCR_USERNAME}"
  : "${GHCR_READ_TOKEN:?cloud requires the existing classic read:packages GHCR_READ_TOKEN}"
  auth="$(mktemp -d)"
  trap 'rm -rf "$auth"' EXIT
  chmod 700 "$auth"
  printf '%s\n' '{"auths":{"ghcr.io":{}}}' >"$auth/config.json"
  printf '%s' "$GHCR_READ_TOKEN" |
    docker --config "$auth" login ghcr.io --username "$GHCR_USERNAME" --password-stdin >/dev/null
  docker --config "$auth" pull "$image" >&2
  rm -rf "$auth"
  mkdir "$auth"
  printf '%s\n' '{"auths":{"ghcr.io":{}}}' >"$auth/config.json"
  unset GHCR_READ_TOKEN GHCR_USERNAME GH_PAT GH_TOKEN GITHUB_TOKEN
  export DOCKER_CONFIG="$auth"
  local args=(--workspace-folder "$root" --mount-git-worktree-common-dir --remote-env "STANDARDS_PIN=$STANDARDS_PIN"
    --remote-env CLAUDE_CODE_REMOTE=true)
  "${cli[@]}" read-configuration --workspace-folder "$root" --include-merged-configuration >/dev/null
  "${cli[@]}" up "${args[@]}" --skip-post-create --default-user-env-probe none >&2
  # shellcheck disable=SC2016
  "${cli[@]}" exec "${args[@]}" bash -c 'source scripts/common/standards-pin.sh && standards_devcontainer_setup "$PWD" --check-only' >&2
  "${cli[@]}" run-user-commands "${args[@]}" --skip-post-attach --default-user-env-probe none >&2
  "${cli[@]}" exec "${args[@]}" bash -c 'if [ -f scripts/repo-local/session-start-claude.sh ]; then bash scripts/repo-local/session-start-claude.sh >&2 || true; fi' >&2
  printf 'Repository Image ready. Edit the shared host checkout; run project commands with: '
  printf '%q ' "${cli[@]}"
  printf 'exec --workspace-folder %q --mount-git-worktree-common-dir --remote-env STANDARDS_PIN=%s --remote-env CLAUDE_CODE_REMOTE=true mise run <task>. Do not fall back to native host project commands.\n' "$root" "$STANDARDS_PIN"
)

standards_reader_git() {
  # Keep the token in the credential subprocess environment, never Git config
  # shellcheck disable=SC2016
  GIT_TERMINAL_PROMPT=0 git \
    -c credential.helper= \
    -c credential.useHttpPath=true \
    -c http.extraHeader= \
    -c http.https://github.com/.extraHeader= \
    -c 'credential.helper=!f() { if [ "$1" = get ]; then printf "%s\n" "username=x-access-token" "password=$GH_PAT"; fi; }; f' \
    "$@"
}

standards_provision_pin() (
  set -euo pipefail
  local root="$1" mode="${2:-}" url='https://github.com/Rubio-Enterprises/standards.git' pin record scratch
  if [ "${STANDARDS_PIN+x}" = x ]; then
    standards_pin_valid "$STANDARDS_PIN"
  fi
  if [ -z "${GH_PAT:-}" ]; then
    standards_pin_error 'the trusted cloud Setup-script must supply its existing read-only GH_PAT'
    exit 1
  fi
  local mise_bin
  if [ -x "$HOME/.local/bin/mise" ]; then
    mise_bin="$HOME/.local/bin/mise"
  elif command -v mise >/dev/null 2>&1; then
    mise_bin="$(command -v mise)"
  else
    (cd / && curl -fsSL https://mise.run | sh >/dev/null)
    mise_bin="$HOME/.local/bin/mise"
  fi
  test -x "$mise_bin"
  pin="$(standards_reader_git ls-remote --exit-code "$url" refs/heads/main | awk '{print $1}')"
  standards_pin_valid "$pin"
  if [ "${STANDARDS_PIN+x}" = x ] && [ "$STANDARDS_PIN" != "$pin" ]; then
    standards_pin_error 'supplied pin disagrees with independently resolved main'
    exit 1
  fi
  if [ -e "$root/.standards-config" ] || [ -L "$root/.standards-config" ]; then
    # Refuse to destroy edits or an unrelated checkout while refreshing a snapshot
    standards_verify_checkout "$root" "$(git -C "$root/.standards-config" rev-parse HEAD)"
  fi
  scratch="$(mktemp -d "$root/.standards-provision.XXXXXX")"
  local installed=false had_previous=false complete=false record_temp=''
  trap '
    if [ "$complete" != true ] && [ "$installed" = true ]; then
      rm -rf "$root/.standards-config"
    fi
    if [ "$complete" != true ] && [ "$had_previous" = true ]; then
      mv "$scratch/previous" "$root/.standards-config"
    fi
    [ -z "$record_temp" ] || rm -f "$record_temp"
    rm -rf "$scratch"
  ' EXIT
  standards_reader_git clone --no-checkout "$url" "$scratch/checkout"
  git -C "$scratch/checkout" checkout --detach "$pin"
  mv "$scratch/checkout" "$scratch/.standards-config"
  standards_verify_checkout "$scratch" "$pin"
  if [ -d "$root/.standards-config" ]; then
    mv "$root/.standards-config" "$scratch/previous"
    had_previous=true
  fi
  mv "$scratch/.standards-config" "$root/.standards-config"
  installed=true
  STANDARDS_PIN="$pin" "$mise_bin" trust "$root/.mise.toml"
  if [ "$mode" != --bootstrap-repository ]; then
    standards_require_ready "$root" "$pin" "$mise_bin"
  fi
  record="$(standards_pin_record "$root")"
  umask 077
  mkdir -p "$(dirname "$record")"
  record_temp="$(mktemp "$(dirname "$record")/.pin.XXXXXX")"
  printf '%s\n' "$pin" >"$record_temp"
  mv "$record_temp" "$record"
  complete=true
)
